interface EntityOptions {
    userId?: string;
    agentId?: string;
    appId?: string;
    runId?: string;
}
interface AddMemoryOptions extends EntityOptions {
    metadata?: Record<string, any>;
    infer?: boolean;
    customCategories?: custom_categories[];
    customInstructions?: string;
    timestamp?: number;
    structuredDataSchema?: Record<string, any>;
}
interface SearchMemoryOptions {
    filters?: Record<string, any>;
    metadata?: Record<string, any>;
    topK?: number;
    threshold?: number;
    rerank?: boolean;
    latestOnly?: boolean;
    fields?: string[];
    categories?: string[];
}
interface GetAllMemoryOptions {
    filters?: Record<string, any>;
    page?: number;
    pageSize?: number;
    startDate?: string;
    endDate?: string;
    latestOnly?: boolean;
    categories?: string[];
}
interface DeleteAllMemoryOptions extends EntityOptions {
}
interface DeleteMemoryOptions {
    /**
     * When `true`, also delete the older memories this one superseded (the v3
     * linked chain), transitively — the delete-side counterpart of `latestOnly`.
     * Off by default. Serialized as `delete_linked`.
     */
    deleteLinked?: boolean;
}
interface ProjectOptions {
    fields?: string[];
}
interface PromptUpdatePayload {
    customInstructions?: string;
    customCategories?: custom_categories[];
    retrievalCriteria?: any[];
    version?: string;
    memoryDepth?: string | null;
    usecaseSetting?: string | number;
    multilingual?: boolean;
    /**
     * Toggle Memory Decay for this project. When `true`, search-time ranking
     * boosts recently-used memories and gently dampens stale ones; when `false`,
     * ranking is restored to the pre-decay behaviour. Off by default.
     * See https://docs.mem0.ai/platform/features/memory-decay
     */
    decay?: boolean;
    [key: string]: any;
}
declare enum Feedback {
    POSITIVE = "POSITIVE",
    NEGATIVE = "NEGATIVE",
    VERY_NEGATIVE = "VERY_NEGATIVE"
}
interface MultiModalMessages {
    type: "image_url";
    image_url: {
        url: string;
    };
}
interface Messages {
    role: "user" | "assistant";
    content: string | MultiModalMessages;
}
interface Message extends Messages {
}
interface MemoryData {
    memory: string;
}
declare enum Event {
    ADD = "ADD",
    UPDATE = "UPDATE",
    DELETE = "DELETE",
    NOOP = "NOOP"
}
interface Memory {
    id: string;
    messages?: Array<Messages>;
    event?: Event | string;
    data?: MemoryData | null;
    memory?: string;
    userId?: string;
    hash?: string;
    categories?: Array<string>;
    createdAt?: Date;
    updatedAt?: Date;
    memoryType?: string;
    score?: number;
    metadata?: any | null;
    owner?: string | null;
    agentId?: string | null;
    appId?: string | null;
    runId?: string | null;
}
interface MemoryHistory {
    id: string;
    memoryId: string;
    input: Array<Messages>;
    oldMemory: string | null;
    newMemory: string | null;
    userId: string;
    categories: Array<string>;
    event: Event | string;
    createdAt: Date;
    updatedAt: Date;
}
interface MemoryUpdateBody {
    memoryId: string;
    text: string;
}
interface User {
    id: string;
    name: string;
    createdAt: Date;
    updatedAt: Date;
    totalMemories: number;
    owner: string;
    type: string;
}
interface AllUsers {
    count: number;
    results: Array<User>;
    next: any;
    previous: any;
}
interface PaginatedMemories {
    count: number;
    next: string | null;
    previous: string | null;
    results: Array<Memory>;
}
interface ProjectResponse {
    customInstructions?: string;
    customCategories?: string[];
    [key: string]: any;
}
interface custom_categories {
    [key: string]: any;
}
declare enum WebhookEvent {
    MEMORY_ADDED = "memory_add",
    MEMORY_UPDATED = "memory_update",
    MEMORY_DELETED = "memory_delete",
    MEMORY_CATEGORIZED = "memory_categorize"
}
interface Webhook {
    webhookId?: string;
    name: string;
    url: string;
    project?: string;
    createdAt?: Date;
    updatedAt?: Date;
    isActive?: boolean;
    eventTypes?: WebhookEvent[];
}
interface WebhookCreatePayload {
    name: string;
    url: string;
    eventTypes: WebhookEvent[];
}
interface WebhookUpdatePayload {
    webhookId: string;
    name?: string;
    url?: string;
    eventTypes?: WebhookEvent[];
}
interface FeedbackPayload {
    memoryId: string;
    feedback?: Feedback | null;
    feedbackReason?: string | null;
}
interface CreateMemoryExportPayload {
    schema: Record<string, any>;
    filters: Record<string, any>;
    exportInstructions?: string;
}
interface GetMemoryExportPayload {
    filters?: Record<string, any>;
    memoryExportId?: string;
}

