  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      lastValue = await fn();
      if (predicate(lastValue)) {
        return lastValue;
      }
    } catch (error) {
      lastError = error;
    }

    if (attempt < attempts) {
      await sleep(delayMs);
    }
  }

