const client = new MemoryClient({ apiKey: MEM0_API_KEY });

const notes = [
  {
    messages: [{ role: "user", content: "I file my quarterly tax estimates with my accountant every March." }],
    metadata: { category: "finance", priority: "high" },
  },
  {
