    return response;
  }
  if (response && Array.isArray(response.results)) {
    return response.results;
  }
  if (response && Array.isArray(response.history)) {
    return response.history;
  }
  return [];
}

function memoryText(memory) {
  const parts = [];
  const push = (value) => {
