    memory?.memory,
    memory?.text,
    memory?.content,
    memory?.data?.memory,
    memory?.newMemory,
    memory?.oldMemory,
    ...(Array.isArray(memory?.messages) ? memory.messages.map((message) => message?.content) : []),
  ]
    .filter((value) => typeof value === "string")
    .join("\n");
}

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

